const void *key = argkey;
const void *data = argdata;
size_t hashes[2];
size_t bucket = argbucket;
size_t max_iterations = (size_t(1) << ckh->lg_curbuckets) * (size_t(1) << LG_CKH_BUCKET_CELLS);

while (max_iterations-- > 0) {
    /* Try to insert in the current bucket */
    if (!ckh_try_bucket_insert(ckh, bucket, key, data)) {
        return false;
    }

    /* If we get here, the bucket was full. Evict a random item and try to insert it elsewhere */
    unsigned offset = static_cast<unsigned>(prng_lg_range_u64(&ckh->prng_state, LG_CKH_BUCKET_CELLS));
    ckhc_t *cell = &ckh->tab[(bucket << LG_CKH_BUCKET_CELLS) + offset];
    assert(cell->key != nullptr);

    /* Swap the evicted item with our new item */
    const void *tkey = cell->key;
    const void *tdata = cell->data;
    cell->key = key;
    cell->data = data;
    key = tkey;
    data = tdata;

#ifdef CKH_COUNT
    ckh->nrelocs++;
#endif

    /* Find the alternate bucket for the evicted item */
    ckh->hash(key, hashes);
    size_t tbucket = hashes[1] & ((size_t(1) << ckh->lg_curbuckets) - 1);

    /* If both hashes point to the same bucket, use the other hash */
    if (tbucket == bucket) {
        tbucket = hashes[0] & ((size_t(1) << ckh->lg_curbuckets) - 1);
    }

    /* Check for cycle detection */
    if (tbucket == argbucket) {
        return true;
    }

    bucket = tbucket;
}

return true;

